prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Detalhe Base'
,p_alias=>'DETALHE-BASE'
,p_step_title=>'Detalhe Base'
,p_reload_on_submit=>'A'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function loadDatasetPreview() {',
'',
'    const dataset = apex.item("P2_BASE").getValue();',
'',
'    const status = document.getElementById("preview-status");',
'    const results = document.getElementById("preview-results");',
'',
'    if (!status || !results) {',
'        console.error("Preview containers not found.");',
'        return;',
'    }',
'',
'    results.replaceChildren();',
'',
'    if (!dataset || !dataset.trim()) {',
'        status.textContent = "Nenhum dataset selecionado.";',
'        return;',
'    }',
'',
'    status.textContent = "Carregando dados...";',
'',
'    apex.server.process(',
'        "LOAD_DATASET_PREVIEW",',
'        {',
'            x01: dataset',
'        },',
'        {',
'            dataType: "json",',
'',
'            success: function(data) {',
'',
'                console.log("AJAX response:", data);',
'',
'                if (!data.success) {',
'                    status.textContent =',
'                        "Erro: " +',
'                        (data.error || "Erro desconhecido");',
'                    return;',
'                }',
'',
'                status.textContent =',
'                    "Dataset: " + data.dataset +',
'                    " | Linhas exibidas: " + data.rowCount +',
'                    " | Tempo: " + data.executionTime + "s";',
'',
'                const table = document.createElement("table");',
'',
'                table.className =',
'                    "a-IRR-table dataset-preview-table";',
'',
'                const thead = document.createElement("thead");',
'                const headerRow = document.createElement("tr");',
'',
'                (data.columns || []).forEach(function(col) {',
'',
'                    const th = document.createElement("th");',
'',
'                    th.textContent = col.name;',
'',
'                    headerRow.appendChild(th);',
'                });',
'',
'                thead.appendChild(headerRow);',
'                table.appendChild(thead);',
'',
'                const tbody = document.createElement("tbody");',
'',
'                (data.rows || []).forEach(function(row) {',
'',
'                    const tr = document.createElement("tr");',
'',
'                    row.forEach(function(value) {',
'',
'                        const td = document.createElement("td");',
'',
'                        td.textContent = value ?? "";',
'',
'                        tr.appendChild(td);',
'                    });',
'',
'                    tbody.appendChild(tr);',
'                });',
'',
'                table.appendChild(tbody);',
'                results.appendChild(table);',
'',
'            },',
'',
'            error: function(jqXHR, textStatus, errorThrown) {',
'',
'                console.error(',
'                    "AJAX Response:",',
'                    jqXHR.responseText',
'                );',
'',
'                status.textContent =',
'                    "Erro ao carregar dados: " +',
'                    (errorThrown || textStatus);',
'            }',
'        }',
'    );',
'}',
