'',
'function copyDatasetSQL() {',
'',
'    const sqlElement =',
'        document.getElementById("dataset-sql-code");',
'',
'    if (!sqlElement) {',
unistr('        apex.message.alert("SQL n\00E3o encontrado.");'),
'        return;',
'    }',
'',
'    const sql = sqlElement.textContent;',
'',
'    navigator.clipboard.writeText(sql)',
'        .then(function() {',
'',
'            apex.message.showPageSuccess(',
unistr('                "SQL copiado para a \00E1rea de transfer\00EAncia!"'),
'            );',
'',
'        })',
'        .catch(function(error) {',
'',
'            console.error("Erro ao copiar SQL:", error);',
'',
'            apex.message.alert(',
unistr('                "N\00E3o foi poss\00EDvel copiar o SQL."'),
'            );',
'',
'        });',
'}'))
