,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    c.column_name as "Nome Coluna",',
unistr('    cc.comments AS "Descri\00E7\00E3o",'),
'    c.data_type as "Data Type",',
'    c.data_length as "Tamanho Campo",',
'    c.nullable "Aceita Nulo",',
'    s.num_distinct "Valores Distintos",',
'    s.num_nulls "Qtde Nulos",',
'',
'    CASE',
'        WHEN c.data_type IN (''VARCHAR2'', ''CHAR'', ''NVARCHAR2'', ''NCHAR'')',
'        THEN NULL',
'        ELSE decode_raw_value(s.low_value, c.data_type)',
'    END AS "Menor Valor",',
'',
'    CASE',
'        WHEN c.data_type IN (''VARCHAR2'', ''CHAR'', ''NVARCHAR2'', ''NCHAR'')',
'        THEN NULL',
'        ELSE decode_raw_value(s.high_value, c.data_type)',
'    END AS "Maior Valor",',
'',
'    CASE',
'        WHEN c.data_type IN (''VARCHAR2'', ''CHAR'', ''NVARCHAR2'', ''NCHAR'')',
'        THEN NULL',
'        ELSE TO_CHAR(s.density, ''FM0.0000'')',
'    END AS "Densidade"',
'',
'FROM user_tab_columns c',
'',
'LEFT JOIN user_tab_col_statistics s',
'    ON c.table_name = s.table_name',
'   AND c.column_name = s.column_name',
'',
'LEFT JOIN user_col_comments cc',
'    ON c.table_name = cc.table_name',
'   AND c.column_name = cc.column_name',
'',
'WHERE c.table_name = :P2_BASE',
'',
'ORDER BY c.column_id;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>10
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
