wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(10868626205755648)
,p_name=>'Data Preview (Apenas 10 Linhas)'
,p_static_id=>'data-preview'
,p_region_name=>'DATA_PREVIEW'
,p_parent_plug_id=>wwv_flow_imp.id(16274827049513605)
,p_template=>4073835273271169698
,p_display_sequence=>120
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_table_name VARCHAR2(128);',
'    l_headers    VARCHAR2(32767);',
'    l_columns    VARCHAR2(32767);',
'    l_aliases    VARCHAR2(32767);',
'    l_sql        VARCHAR2(32767);',
'BEGIN',
'    -- Validate table name',
'    SELECT table_name',
'      INTO l_table_name',
'      FROM user_tables',
'     WHERE table_name = UPPER(:P2_BASE);',
'',
'    -- Generate column names and data expressions',
'    SELECT',
'        LISTAGG(',
'            '''''''' || REPLACE(column_name, '''''''', '''''''''''') ||',
'            '''''' AS COL'' || LPAD(rn, 2, ''0''),',
'            '', ''',
'        ) WITHIN GROUP (ORDER BY rn),',
'',
'        LISTAGG(',
'            ''CAST("'' || REPLACE(column_name, ''"'', ''""'') ||',
'            ''" AS VARCHAR2(4000)) AS COL'' || LPAD(rn, 2, ''0''),',
'            '', ''',
'        ) WITHIN GROUP (ORDER BY rn),',
'',
'        LISTAGG(',
'            ''COL'' || LPAD(rn, 2, ''0''),',
'            '', ''',
'        ) WITHIN GROUP (ORDER BY rn)',
'',
'    INTO l_headers, l_columns, l_aliases',
'',
'    FROM (',
'        SELECT',
'            column_name,',
'            ROW_NUMBER() OVER (ORDER BY column_id) AS rn',
'        FROM user_tab_columns',
'        WHERE table_name = l_table_name',
'    );',
'',
'    -- Generate SQL',
'    l_sql :=',
'        ''SELECT '' || l_aliases || '' FROM ('' ||',
'        ''SELECT 0 AS row_order, '' || l_headers || '' FROM DUAL '' ||',
'        ''UNION ALL '' ||',
'        ''SELECT 1 AS row_order, '' || l_columns ||',
'        '' FROM (SELECT * FROM "'' ||',
'        REPLACE(l_table_name, ''"'', ''""'') ||',
'        ''" FETCH FIRST 10 ROWS ONLY)'' ||',
'        '') ORDER BY row_order'';',
'',
'    RETURN l_sql;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''SELECT CAST(NULL AS VARCHAR2(4000)) AS COL01 '' ||',
'               ''FROM DUAL WHERE 1 = 0'';',
'END;'))
,p_query_order_by_type=>'STATIC'
,p_query_order_by=>'1 desc'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_BASE'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_plug_query_max_columns=>200
