,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '//const downloadUrl = apex.item("P2_DOWNLOAD_URL").getValue();',
    '//',
    '//if (downloadUrl) {',
    '//',
    '//    window.open(',
    '//        downloadUrl,',
    '//        "_blank",',
    '//        "noopener,noreferrer"',
    '//    );',
    '//',
    '//} else {',
    '//',
    '//    apex.message.alert(',
    unistr('//        "Nenhum arquivo dispon\00EDvel para download."'),
    '//    );',
    '//',
    '//}',
    '',
    'function downloadAllDatasetFiles() {',
    '',
    '    const downloadData = apex.item("P2_DOWNLOAD_URL").getValue();',
    '',
    '    if (!downloadData) {',
    unistr('        apex.message.alert("Nenhum arquivo dispon\00EDvel para download.");'),
    '        return;',
    '    }',
    '',
    '    try {',
    '        const urls = JSON.parse(downloadData);',
    '',
    '        if (!Array.isArray(urls) || urls.length === 0) {',
    '            apex.message.alert("Nenhum arquivo encontrado.");',
    '            return;',
    '        }',
    '',
    '        const allowedOrigin =',
    '            "https://objectstorage.sa-vinhedo-1.oraclecloud.com";',
    '',
    '        const validUrls = urls.filter(function(url) {',
    '            try {',
    '                const parsed = new URL(url);',
    '                return parsed.origin === allowedOrigin &&',
    '                       parsed.pathname.startsWith("/p/");',
    '            } catch (e) {',
    '                return false;',
    '            }',
    '        });',
    '',
    '        if (validUrls.length === 0) {',
    unistr('            apex.message.alert("Nenhum link v\00E1lido encontrado.");'),
    '            return;',
    '        }',
    '',
    '        let opened = 0;',
    '',
    '        validUrls.forEach(function(url) {',
    '',
    '            const tab = window.open(',
    '                url,',
    '                "_blank"',
    '            );',
    '',
    '            if (tab) {',
    '                tab.opener = null;',
    '                opened++;',
    '            }',
    '',
    '        });',
    '',
    '        if (opened < validUrls.length) {',
    '            apex.message.alert(',
    '                "O navegador pode ter bloqueado alguns downloads. " +',
    unistr('                "Permita pop-ups e m\00FAltiplos downloads para esta aplica\00E7\00E3o."'),
    '            );',
    '        }',
    '',
    '    } catch (error) {',
    '        console.error("Erro ao processar links de download:", error);',
    '        apex.message.alert("Erro ao preparar os downloads.");',
    '    }',
    '}',
    '',
    'downloadAllDatasetFiles();')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20261010213844Z')
,p_updated_on=>wwv_flow_imp.dz('20261010223116Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(16275035178513607)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete_dataset'
,p_static_id=>'delete-dataset'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_table_name VARCHAR2(128);',
'    l_exists     NUMBER;',
'    l_owner      VARCHAR2(255);',
'',
'BEGIN',
'    -- ==========================================',
'    -- 1. GET DATASET NAME',
'    -- ==========================================',
'',
'    l_table_name := UPPER(TRIM(:P2_BASE));',
'',
'    IF l_table_name IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select a dataset to delete.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 2. VALIDATE TABLE NAME',
'    -- ==========================================',
'',
'    IF NOT REGEXP_LIKE(',
'        l_table_name,',
'        ''^[A-Z][A-Z0-9]*(_[A-Z0-9]+)+$''',
'    ) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Invalid dataset name.''',
'        );',
'    END IF;',
'',
'    l_table_name := DBMS_ASSERT.SIMPLE_SQL_NAME(',
'        l_table_name',
'    );',
'',
'    -- ==========================================',
'    -- 3. CHECK DATASET REGISTRATION',
'    -- ==========================================',
'',
'    SELECT datasets_usuario',
'      INTO l_owner',
'      FROM datasets',
'     WHERE UPPER(datasets_nome) = l_table_name;',
'',
'    -- ==========================================',
'    -- 4. VERIFY DATASET OWNERSHIP',
'    -- ==========================================',
'',
'    IF UPPER(l_owner) <> UPPER(:APP_USER) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
'            ''You are not authorized to delete this dataset.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 5. CHECK PHYSICAL TABLE EXISTS',
'    -- ==========================================',
'',
'    SELECT COUNT(*)',
'      INTO l_exists',
'      FROM user_tables',
'     WHERE table_name = l_table_name;',
'',
'    IF l_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20004,',
'            ''The physical dataset table does not exist.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 6. DROP PHYSICAL TABLE',
'    -- ==========================================',
'',
'    EXECUTE IMMEDIATE',
'        ''DROP TABLE '' || l_table_name || '' PURGE'';',
'',
'    -- ==========================================',
'    -- 7. DELETE DATASET METADATA',
'    -- ==========================================',
'',
'    DELETE FROM datasets',
'     WHERE UPPER(datasets_nome) = l_table_name',
'       AND UPPER(datasets_usuario) = UPPER(:APP_USER);',
'',
'    -- ==========================================',
'    -- 8. SUCCESS MESSAGE',
'    -- ==========================================',
'',
'    APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'        ''Dataset '' || l_table_name ||',
'        '' deleted successfully!'';',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'',
'        APEX_ERROR.ADD_ERROR(',
'            p_message =>',
'                ''Dataset not found in the DATASETS control table.'',',
'            p_display_location =>',
'                APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'',
'    WHEN TOO_MANY_ROWS THEN',
'',
'        APEX_ERROR.ADD_ERROR(',
'            p_message =>',
'                ''Multiple dataset records found with this name.'',',
'            p_display_location =>',
'                APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'',
'    WHEN OTHERS THEN',
'',
'        APEX_ERROR.ADD_ERROR(',
'            p_message => SQLERRM,',
'            p_display_location =>',
'                APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(16274912932513606)
,p_internal_uid=>16275035178513607
,p_created_on=>wwv_flow_imp.dz('20261010182502Z')
,p_updated_on=>wwv_flow_imp.dz('20261010182731Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
