'DECLARE',
'    -- Dataset information',
'    l_table_name       VARCHAR2(128);',
'    l_sql              VARCHAR2(32767);',
'    l_exists           NUMBER;',
'',
'    -- Object Storage',
'    l_file_prefix      VARCHAR2(255);',
'    l_file_uri         VARCHAR2(4000);',
'    l_actual_file_name VARCHAR2(4000);',
'    l_file_count       NUMBER := 0;',
'',
'    -- PAR',
'    l_par_url          VARCHAR2(4000);',
'    l_download_urls    CLOB;',
'    l_expires_at       TIMESTAMP WITH TIME ZONE;',
'',
'    l_details',
'        DBMS_CLOUD_OCI_OBJECT_STORAGE_CREATE_PREAUTHENTICATED_REQUEST_DETAILS_T;',
'',
'    l_response',
'        DBMS_CLOUD_OCI_OBS_OBJECT_STORAGE_CREATE_PREAUTHENTICATED_REQUEST_RESPONSE_T;',
'',
'    -- OCI configuration',
'    c_bucket_url CONSTANT VARCHAR2(2000) :=',
'        ''https://objectstorage.sa-vinhedo-1.oraclecloud.com'' ||',
'        ''/n/idi1o0a010nx'' ||',
'        ''/b/bucket-cnpj-export/o/'';',
'',
'BEGIN',
'',
'    -- ==========================================',
'    -- 1. CLEAR PREVIOUS DOWNLOAD',
'    -- ==========================================',
'',
'    :P2_DOWNLOAD_URL := NULL;',
'',
'    -- ==========================================',
'    -- 2. GET TABLE NAME',
'    -- ==========================================',
'',
'    l_table_name := UPPER(TRIM(:P2_BASE));',
'',
'    -- ==========================================',
'    -- 3. VALIDATE TABLE NAME',
'    -- ==========================================',
'',
'    IF l_table_name IS NULL',
'       OR NOT REGEXP_LIKE(',
'           l_table_name,',
'           ''^[A-Z][A-Z0-9_]*$''',
'       )',
'    THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invalid dataset name.''',
'        );',
'    END IF;',
'',
'    l_table_name :=',
'        DBMS_ASSERT.SIMPLE_SQL_NAME(l_table_name);',
'',
'    -- ==========================================',
'    -- 4. CHECK TABLE EXISTS',
'    -- ==========================================',
'',
'    SELECT COUNT(*)',
'      INTO l_exists',
'      FROM ALL_TABLES',
'     WHERE OWNER = ''DEMO''',
'       AND TABLE_NAME = l_table_name;',
'',
'    IF l_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Dataset table does not exist in DEMO schema.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 5. BUILD SQL',
'    -- ==========================================',
'',
'    l_sql :=',
'        ''SELECT * FROM DEMO.'' || l_table_name;',
'',
'    -- ==========================================',
'    -- 6. GENERATE UNIQUE FILE PREFIX',
'    -- ==========================================',
'',
'    l_file_prefix :=',
'        LOWER(l_table_name) || ''_'' ||',
'        TO_CHAR(',
'            SYSTIMESTAMP,',
'            ''YYYYMMDD_HH24MISSFF3''',
'        ) || ''_'' ||',
'        LOWER(RAWTOHEX(SYS_GUID()));',
'',
'    -- ==========================================',
'    -- 7. BUILD OBJECT STORAGE URI',
'    -- ==========================================',
'',
'    l_file_uri :=',
'        c_bucket_url || l_file_prefix;',
'',
'    -- ==========================================',
'    -- 8. EXPORT DATASET TO OBJECT STORAGE',
'    -- ==========================================',
'',
'    DBMS_CLOUD.EXPORT_DATA(',
'        credential_name => ''OBJ_STORE_CRED'',',
'        file_uri_list   => l_file_uri,',
'        query           => l_sql,',
'        format          => JSON_OBJECT(',
'            ''type''        VALUE ''csv'',',
'            ''delimiter''   VALUE '','',',
'            ''header''      VALUE TRUE,',
'            ''maxfilesize'' VALUE 1610612736',
'        )',
'    );',
'',
'    -- ==========================================',
'    -- 9. INITIALIZE JSON ARRAY',
'    -- ==========================================',
'',
'    APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'',
'    APEX_JSON.OPEN_ARRAY;',
'',
'    l_expires_at := SYSTIMESTAMP + INTERVAL ''1'' HOUR;',
'',
'    -- ==========================================',
'    -- 10. FIND ALL EXPORTED FILES',
'    -- ==========================================',
'',
'    FOR r IN (',
'        SELECT object_name',
'          FROM TABLE(',
'              DBMS_CLOUD.LIST_OBJECTS(',
'                  credential_name => ''OBJ_STORE_CRED'',',
'                  location_uri    => c_bucket_url',
'              )',
'          )',
'         WHERE SUBSTR(',
'                   object_name,',
'                   1,',
'                   LENGTH(l_file_prefix) + 1',
'               ) = l_file_prefix || ''_''',
'           AND LOWER(object_name) LIKE ''%.csv''',
'         ORDER BY object_name',
'    )',
'    LOOP',
'',
'        l_file_count := l_file_count + 1;',
'',
'        l_actual_file_name := r.object_name;',
'',
'        -- ======================================',
'        -- 11. CREATE PAR FOR EACH FILE',
'        -- ======================================',
'',
'        l_details :=',
'            DBMS_CLOUD_OCI_OBJECT_STORAGE_CREATE_PREAUTHENTICATED_REQUEST_DETAILS_T(',
'                name =>',
'                    ''APEX_EXPORT_'' ||',
'                    SUBSTR(',
'                        REPLACE(l_file_prefix, ''_'', ''''),',
'                        1,',
'                        40',
'                    ) ||',
'                    ''_'' ||',
'                    l_file_count,',
'',
'                bucket_listing_action => NULL,',
'',
'                object_name => l_actual_file_name,',
'',
'                access_type => ''ObjectRead'',',
'',
'                time_expires => l_expires_at',
'            );',
'',
'        l_response :=',
'            DBMS_CLOUD_OCI_OBS_OBJECT_STORAGE.CREATE_PREAUTHENTICATED_REQUEST(',
'                namespace_name => ''idi1o0a010nx'',',
'                bucket_name    => ''bucket-cnpj-export'',',
'',
'                create_preauthenticated_request_details => l_details,',
'',
'                region          => ''sa-vinhedo-1'',',
'                credential_name => ''OBJ_STORE_CRED''',
'            );',
'',
'        -- Validate response',
'        IF l_response.status_code NOT BETWEEN 200 AND 299 THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20005,',
'                ''PAR creation failed for file: '' ||',
'                l_actual_file_name',
'            );',
'',
'        END IF;',
'',
'        -- ======================================',
'        -- 12. BUILD DOWNLOAD URL',
'        -- ======================================',
'',
'        l_par_url :=',
'            ''https://objectstorage.sa-vinhedo-1.oraclecloud.com'' ||',
'            l_response.response_body.access_uri;',
'',
'        -- ======================================',
'        -- 13. ADD URL TO JSON ARRAY',
'        -- ======================================',
'',
'        APEX_JSON.WRITE(l_par_url);',
'',
'    END LOOP;',
'',
'    -- ==========================================',
'    -- 14. VALIDATE FILE COUNT',
'    -- ==========================================',
'',
'    IF l_file_count = 0 THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
'            ''Export completed, but no CSV files were found.''',
'        );',
'',
'    END IF;',
'',
'    -- ==========================================',
'    -- 15. CLOSE JSON ARRAY',
'    -- ==========================================',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'',
'    l_download_urls := APEX_JSON.GET_CLOB_OUTPUT;',
'',
'    APEX_JSON.FREE_OUTPUT;',
'',
'    -- ==========================================',
'    -- 16. SAVE URLS IN APEX SESSION STATE',
'    -- ==========================================',
'',
'    :P2_DOWNLOAD_URL := l_download_urls;',
'',
'    -- ==========================================',
'    -- 17. SUCCESS MESSAGE',
'    -- ==========================================',
'',
'    APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'        ''Dataset exported successfully! '' ||',
'        l_file_count ||',
'        '' CSV file(s) available for download.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(16275923106513616)
,p_internal_uid=>13901725068280603
,p_created_on=>wwv_flow_imp.dz('20261010010748Z')
,p_updated_on=>wwv_flow_imp.dz('20261010222724Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(16275205432513609)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_DATASET_PREVIEW'
,p_static_id=>'load-dataset-preview'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_table_name    VARCHAR2(128);',
'    l_sql           VARCHAR2(32767);',
'',
'    l_cursor        INTEGER;',
'    l_column_count  INTEGER;',
'    l_columns       DBMS_SQL.DESC_TAB2;',
'',
'    l_value         VARCHAR2(4000);',
'    l_status        INTEGER;',
'',
'    l_rows          INTEGER := 0;',
'    l_start         NUMBER;',
'    l_elapsed       NUMBER;',
'',
'    l_exists        NUMBER;',
'    l_error         VARCHAR2(4000);',
'    l_json          CLOB;',
'',
'BEGIN',
'    -- Start timer',
'    l_start := DBMS_UTILITY.GET_TIME;',
'',
'    -- Get dataset name',
'    l_table_name :=',
'        UPPER(TRIM(APEX_APPLICATION.G_X01));',
'',
'    -- Validate name',
'    IF l_table_name IS NULL',
'       OR NOT REGEXP_LIKE(',
'           l_table_name,',
'           ''^[A-Z][A-Z0-9_]*$''',
'       )',
'    THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invalid dataset name.''',
'        );',
'    END IF;',
'',
'    l_table_name :=',
'        DBMS_ASSERT.SIMPLE_SQL_NAME(l_table_name);',
'',
'    -- Check dataset registration',
'--    SELECT COUNT(*)',
'--      INTO l_exists',
'--      FROM DEMO.DATASETS',
'--     WHERE UPPER(TRIM(DATASETS_NOME)) = l_table_name;',
'--',
'--    IF l_exists = 0 THEN',
'--        RAISE_APPLICATION_ERROR(',
'--            -20002,',
'--            ''Dataset not found in DEMO.DATASETS.''',
'--        );',
'--    END IF;',
'',
'    -- Check physical table',
'    SELECT COUNT(*)',
'      INTO l_exists',
'      FROM ALL_TABLES',
'     WHERE OWNER = ''DEMO''',
'       AND TABLE_NAME = l_table_name;',
'',
'    IF l_exists = 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
'            ''Physical table not found in DEMO schema.''',
'        );',
'    END IF;',
'',
'    -- Build SELECT',
'    l_sql :=',
'        ''SELECT * FROM DEMO.'' || l_table_name;',
'',
'    -- Open cursor',
'    l_cursor := DBMS_SQL.OPEN_CURSOR;',
'',
'    DBMS_SQL.PARSE(',
'        l_cursor,',
'        l_sql,',
'        DBMS_SQL.NATIVE',
'    );',
'',
'    -- Describe columns',
'    DBMS_SQL.DESCRIBE_COLUMNS2(',
'        l_cursor,',
'        l_column_count,',
'        l_columns',
'    );',
'',
'    -- Define columns',
'    FOR i IN 1 .. l_column_count LOOP',
'        DBMS_SQL.DEFINE_COLUMN(',
'            l_cursor,',
'            i,',
'            l_value,',
'            4000',
'        );',
'    END LOOP;',
'',
'    -- Execute query',
'    l_status := DBMS_SQL.EXECUTE(l_cursor);',
'',
'    -- Initialize JSON',
'    APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'',
'    APEX_JSON.OPEN_OBJECT;',
'',
'    APEX_JSON.WRITE(''success'', TRUE);',
'    APEX_JSON.WRITE(''dataset'', l_table_name);',
'',
'    -- Column headers',
'    APEX_JSON.OPEN_ARRAY(''columns'');',
'',
'    FOR i IN 1 .. l_column_count LOOP',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(',
'            ''name'',',
'            l_columns(i).col_name',
'        );',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'',
'    -- Result rows',
'APEX_JSON.OPEN_ARRAY(''rows'');',
'',
'WHILE l_rows < 100',
'',
'  AND DBMS_SQL.FETCH_ROWS(l_cursor) > 0',
'',
'LOOP',
'',
'    APEX_JSON.OPEN_ARRAY;',
'',
'    FOR i IN 1 .. l_column_count LOOP',
'',
'        l_value := NULL;',
'',
'        DBMS_SQL.COLUMN_VALUE(',
'',
'            l_cursor,',
'',
'            i,',
'',
'            l_value',
'',
'        );',
'',
'        -- Write column value, preserving NULL positions',
'',
'        APEX_JSON.WRITE(l_value);',
'',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'',
'    l_rows := l_rows + 1;',
'',
'END LOOP;',
'',
'APEX_JSON.CLOSE_ARRAY;',
'',
'    -- Close cursor',
'    DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'    l_cursor := NULL;',
'',
'    -- Execution statistics',
'    l_elapsed :=',
'        (DBMS_UTILITY.GET_TIME - l_start) / 100;',
'',
'    APEX_JSON.WRITE(''rowCount'', l_rows);',
'    APEX_JSON.WRITE(''executionTime'', l_elapsed);',
'',
'    APEX_JSON.CLOSE_OBJECT;',
'',
'    -- Return JSON',
'    l_json := APEX_JSON.GET_CLOB_OUTPUT;',
'',
'    APEX_JSON.FREE_OUTPUT;',
'',
'    SYS.HTP.PRN(l_json);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        l_error := SQLERRM;',
'',
'        -- Close cursor safely',
'        BEGIN',
'            IF l_cursor IS NOT NULL THEN',
'                IF DBMS_SQL.IS_OPEN(l_cursor) THEN',
'                    DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'                END IF;',
'            END IF;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'',
'        -- Release incomplete JSON',
'        BEGIN',
'            APEX_JSON.FREE_OUTPUT;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'',
'        -- Build error JSON',
'        APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(''success'', FALSE);',
'        APEX_JSON.WRITE(''error'', l_error);',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'',
'        l_json := APEX_JSON.GET_CLOB_OUTPUT;',
'',
'        APEX_JSON.FREE_OUTPUT;',
'',
'        SYS.HTP.PRN(l_json);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>16275205432513609
,p_created_on=>wwv_flow_imp.dz('20261010183259Z')
,p_updated_on=>wwv_flow_imp.dz('20261010190434Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14085082708558930)
,p_process_sequence=>60
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_COLUNAS'
,p_static_id=>'set-colunas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- Total number of columns',
'    SELECT COUNT(*)',
'    INTO :P2_COLUNAS',
'    FROM user_tab_columns c',
'    WHERE c.table_name = :P2_BASE;',
'EXCEPTION',
