 p_id=>wwv_flow_imp.id(14083686974558916)
,p_process_sequence=>40
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_TAMANHO'
,p_static_id=>'set-tamanho'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT',
'        TO_CHAR(',
'            ROUND(seg.bytes / 1024 / 1024 / 1024, 2),',
'            ''FM0.00''',
'        )',
'    INTO :P2_TAMANHO',
'',
'    FROM user_tables t',
'',
'    LEFT JOIN (',
'        SELECT',
'            segment_name,',
'            SUM(bytes) AS bytes',
'        FROM user_segments',
'        WHERE segment_type IN (',
'            ''TABLE'',',
'            ''TABLE PARTITION'',',
'            ''TABLE SUBPARTITION''',
'        )',
'        GROUP BY segment_name',
'    ) seg',
'        ON t.table_name = seg.segment_name',
'',
'    WHERE t.table_name = :P2_BASE;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P2_TAMANHO := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14083686974558916
,p_created_on=>wwv_flow_imp.dz('20261010014320Z')
,p_updated_on=>wwv_flow_imp.dz('20261010225616Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
