prompt --application/pages/page_00003
begin
wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'Criar Dataset'
,p_alias=>'CRIAR-DATASET'
,p_step_title=>'Criar Dataset'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// =====================================================',
'// GLOBAL VARIABLES',
'// =====================================================',
'',
'let sqlExecuted = false;',
'let lastExecutedSQL = "";',
'',
'',
'// =====================================================',
'// SHOW / HIDE RESULTS',
'// =====================================================',
'',
'function toggleResults() {',
'',
'    const sql = apex.item("P3_SQL").getValue();',
'',
'    if (!sql || !sql.trim() || !sqlExecuted) {',
'        $("#RESULTS").hide();',
'    } else {',
'        $("#RESULTS").show();',
'    }',
'}',
'',
'',
'// =====================================================',
'// SHOW / HIDE NEXT BUTTON',
'// =====================================================',
'',
'function toggleNextButton() {',
'',
'    $("#NEXT_BTN").toggle(sqlExecuted);',
'',
'}',
'',
'',
'// =====================================================',
'// RESET QUERY EXECUTION STATE',
'// =====================================================',
'',
'function resetSQLExecution() {',
'',
'    sqlExecuted = false;',
'    lastExecutedSQL = "";',
'',
'    toggleNextButton();',
'    toggleResults();',
'',
'}',
'',
'',
'// =====================================================',
'// EXECUTE SQL',
'// =====================================================',
'',
'function executeSQL() {',
'',
'    const sql = apex.item("P3_SQL").getValue();',
'',
'    const region = document.getElementById("RESULTS");',
'',
'    // Reset client-side execution state',
'    resetSQLExecution();',
'',
'    if (!region) {',
'        console.error("RESULTS region not found.");',
'        apex.message.alert("RESULTS region not found.");',
'        return;',
'    }',
'',
'    // Find or create result containers',
'    let results = document.getElementById("sql-results");',
'    let status = document.getElementById("sql-status");',
'',
'    if (!status) {',
'        status = document.createElement("div");',
'        status.id = "sql-status";',
'        region.appendChild(status);',
'    }',
'',
'    if (!results) {',
'        results = document.createElement("div");',
'        results.id = "sql-results";',
'        region.appendChild(results);',
'    }',
'',
'    // Clear previous results',
'    results.replaceChildren();',
'    status.textContent = "";',
'',
'    // Validate SQL input',
'    if (!sql || !sql.trim()) {',
'',
'        apex.message.alert(',
'            "Please enter a SELECT query."',
'        );',
'',
'        return;',
'    }',
'',
'    // Display loading status',
'    $("#RESULTS").show();',
'',
'    status.textContent = "Executing query...";',
'',
'    // Execute AJAX callback',
'    apex.server.process(',
'        "EXECUTE_SELECT",',
'        {',
'            x01: sql',
'        },',
'        {',
'            dataType: "json",',
'',
'            success: function(data) {',
'',
'                // SQL execution failed',
'                if (!data.success) {',
'',
'                    sqlExecuted = false;',
'',
'                    toggleNextButton();',
'',
'                    status.textContent =',
'                        "SQL Error: " +',
'                        (data.error || "Unknown error");',
'',
'                    $("#RESULTS").show();',
'',
'                    return;',
'                }',
'',
'                // SQL executed successfully',
'                sqlExecuted = true;',
'',
'                lastExecutedSQL = sql;',
'',
'                // Show NEXT button',
'                toggleNextButton();',
'',
'                // Show results',
'                $("#RESULTS").show();',
'',
'                // Execution information',
'                status.textContent =',
'                    "Query executed successfully | " +',
'                    "Rows: " + data.rowCount +',
'                    " | Time: " +',
'                    data.executionTime + " sec";',
'',
'                // Create results table',
'                const table =',
'                    document.createElement("table");',
'',
'                table.className =',
'                    "a-IRR-table sql-preview-table";',
'',
'                // Table header',
'                const thead =',
'                    document.createElement("thead");',
'',
'                const headerRow =',
'                    document.createElement("tr");',
'',
'                (data.columns || []).forEach(function(col) {',
'',
'                    const th =',
'                        document.createElement("th");',
'',
'                    th.textContent = col.name;',
'',
'                    headerRow.appendChild(th);',
'',
'                });',
'',
'                thead.appendChild(headerRow);',
'',
'                table.appendChild(thead);',
'',
'                // Table body',
'                const tbody =',
'                    document.createElement("tbody");',
'',
'                (data.rows || []).forEach(function(row) {',
'',
'                    const tr =',
'                        document.createElement("tr");',
'',
'                    row.forEach(function(value) {',
'',
'                        const td =',
'                            document.createElement("td");',
'',
'                        td.textContent =',
'                            value ?? "";',
'',
'                        tr.appendChild(td);',
'',
'                    });',
'',
'                    tbody.appendChild(tr);',
'',
'                });',
'',
'                table.appendChild(tbody);',
'',
'                // Display results',
'                results.appendChild(table);',
'',
'            },',
'',
'            error: function(',
'                jqXHR,',
'                textStatus,',
'                errorThrown',
'            ) {',
'',
'                sqlExecuted = false;',
'',
'                toggleNextButton();',
'',
'                $("#RESULTS").show();',
'',
'                status.textContent =',
'                    "Error executing SQL: " +',
'                    errorThrown;',
'',
'                console.error(',
'                    "AJAX Response:",',
'                    jqXHR.responseText',
'                );',
'',
'            }',
'        }',
'    );',
'}',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'function loadDatabaseExplorer() {',
'',
'    const tree = document.getElementById("db-tree");',
'',
'    if (!tree) return;',
'',
'    tree.textContent = "Loading tables...";',
'',
'    apex.server.process(',
'        "GET_DB_OBJECTS",',
'        {},',
'        {',
'            dataType: "json",',
'',
'            success: function(data) {',
'',
'                tree.replaceChildren();',
'',
'                (data.tables || []).forEach(function(table) {',
'',
'                    const details = document.createElement("details");',
'                    details.className = "db-table";',
'',
'                    const summary = document.createElement("summary");',
'                    summary.textContent = table.name;',
'',
'                    details.appendChild(summary);',
'',
'                    // Insert table name',
'                    const tableButton = document.createElement("button");',
'                    tableButton.type = "button";',
'                    tableButton.textContent = "+ Insert table";',
'                    tableButton.className = "db-insert-table";',
'',
'                    tableButton.addEventListener("click", function() {',
'                        insertIntoSQL("DEMO." + table.name);',
'                    });',
'',
'                    details.appendChild(tableButton);',
'',
'                    // Columns',
'                    table.columns.forEach(function(col) {',
'                        const row = document.createElement("div");',
'                        row.className = "db-column";',
'',
'                        const button = document.createElement("button");',
'                        button.type = "button";',
'                        button.textContent = col.name;',
'',
'                        // Insert TABLE_NAME.COLUMN_NAME',
'                        button.addEventListener("click", function() {',
'                            const columnReference =',
'                                table.name + "." + col.name;',
'                            insertIntoSQL(columnReference);',
'                        });',
'',
'                        const type = document.createElement("span");',
'                        type.className = "db-column-type";',
'                        type.textContent = col.type;',
'                        row.appendChild(button);',
'                        row.appendChild(type);',
'                        details.appendChild(row);',
'                    });',
'',
'                    tree.appendChild(details);',
'                });',
'',
'            },',
'',
'            error: function(jqXHR) {',
'                tree.textContent = "Error loading database objects.";',
'                console.error(jqXHR.responseText);',
'            }',
'        }',
'    );',
'}',
'',
'function insertIntoSQL(text) {',
'',
'    const editor = document.getElementById("P3_SQL");',
'',
'    if (!editor) return;',
'',
'    const start = editor.selectionStart;',
'    const end = editor.selectionEnd;',
'',
'    const current = editor.value;',
'',
'    editor.value =',
'        current.substring(0, start) +',
'        text +',
'        current.substring(end);',
'',
'    const newPosition = start + text.length;',
'',
'    editor.focus();',
'    editor.setSelectionRange(newPosition, newPosition);',
'',
'    editor.dispatchEvent(',
'        new Event("input", { bubbles: true })',
'    );',
'}',
'',
'function filterDatabaseExplorer() {',
'',
'    const search = document',
'        .getElementById("db-search")',
'        .value',
'        .toUpperCase();',
'',
'    document.querySelectorAll(".db-table").forEach(function(table) {',
'',
'        const name = table.querySelector("summary").textContent;',
'',
'        table.style.display =',
'            name.toUpperCase().includes(search)',
'                ? ""',
'                : "none";',
'    });',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'sqlExecuted = false;',
'lastExecutedSQL = "";',
'',
'$("#RESULTS").hide();',
'$("#NEXT_BTN").hide();',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'',
'loadDatabaseExplorer();',
'',
'document',
'    .getElementById("db-search")',
'    ?.addEventListener("input", filterDatabaseExplorer);'))
