wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(16275694947513613)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DB_OBJECTS'
,p_static_id=>'get-db-objects'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--BEGIN',
'--    APEX_JSON.OPEN_OBJECT;',
'--    APEX_JSON.OPEN_ARRAY(''tables'');',
'--',
'--    FOR t IN (',
'--        SELECT table_name',
'--        FROM all_tables',
'--        WHERE owner = ''DEMO''',
'--          AND table_name NOT LIKE ''BIN$%''',
'--        ORDER BY table_name',
'--    )',
'--    LOOP',
'--        APEX_JSON.OPEN_OBJECT;',
'--',
'--        APEX_JSON.WRITE(''name'', t.table_name);',
'--',
'--        APEX_JSON.OPEN_ARRAY(''columns'');',
'--',
'--        FOR c IN (',
'--            SELECT',
'--                column_name,',
'--                data_type',
'--            FROM all_tab_columns',
'--            WHERE owner = ''DEMO''',
'--              AND table_name = t.table_name',
'--            ORDER BY column_id',
'--        )',
'--        LOOP',
'--            APEX_JSON.OPEN_OBJECT;',
'--            APEX_JSON.WRITE(''name'', c.column_name);',
'--            APEX_JSON.WRITE(''type'', c.data_type);',
'--            APEX_JSON.CLOSE_OBJECT;',
'--        END LOOP;',
'--',
'--        APEX_JSON.CLOSE_ARRAY;',
'--        APEX_JSON.CLOSE_OBJECT;',
'--    END LOOP;',
'--',
'--    APEX_JSON.CLOSE_ARRAY;',
'--    APEX_JSON.CLOSE_OBJECT;',
'--END;',
'',
'',
'BEGIN',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.OPEN_ARRAY(''tables'');',
'',
'    -- Get only tables registered in BASES',
'    FOR t IN (',
'        SELECT DISTINCT',
'            b.BASES_NOME AS TABLE_NAME',
'        FROM DEMO.BASES b',
'        INNER JOIN ALL_TABLES t',
'            ON t.TABLE_NAME = UPPER(TRIM(b.BASES_NOME))',
'           AND t.OWNER = ''DEMO''',
'        WHERE t.TABLE_NAME NOT LIKE ''BIN$%''',
'        ORDER BY TABLE_NAME',
'    )',
'    LOOP',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(',
'            ''name'',',
'            t.TABLE_NAME',
'        );',
'',
'        -- Get columns for each table',
'        APEX_JSON.OPEN_ARRAY(''columns'');',
'',
'        FOR c IN (',
'            SELECT',
'                COLUMN_NAME,',
'                DATA_TYPE',
'            FROM ALL_TAB_COLUMNS',
'            WHERE OWNER = ''DEMO''',
'              AND TABLE_NAME = UPPER(TRIM(t.TABLE_NAME))',
'            ORDER BY COLUMN_ID',
'        )',
'        LOOP',
'            APEX_JSON.OPEN_OBJECT;',
'',
'            APEX_JSON.WRITE(',
'                ''name'',',
'                c.COLUMN_NAME',
'            );',
'',
'            APEX_JSON.WRITE(',
'                ''type'',',
'                c.DATA_TYPE',
'            );',
'',
'            APEX_JSON.CLOSE_OBJECT;',
'        END LOOP;',
'',
'        APEX_JSON.CLOSE_ARRAY;',
'        APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'    APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>16275694947513613
