wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15672767851491119)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'EXECUTE_SELECT'
,p_static_id=>'query'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sql           VARCHAR2(32767);',
'    l_cursor        INTEGER;',
'    l_column_count  INTEGER;',
'    l_columns       DBMS_SQL.DESC_TAB2;',
'    l_value         VARCHAR2(4000);',
'    l_status        INTEGER;',
'    l_rows          INTEGER := 0;',
'    l_start         NUMBER;',
'    l_elapsed       NUMBER;',
'    l_error         VARCHAR2(4000);',
'    l_json          CLOB;',
'',
'BEGIN',
'    -- Reset execution status',
'    :P3_EXECUTED := ''N'';',
'    :P3_QUERY := NULL;',
'',
'    l_start := DBMS_UTILITY.GET_TIME;',
'',
'    l_sql := TRIM(APEX_APPLICATION.G_X01);',
'',
'    -- Basic SELECT validation',
'    IF l_sql IS NULL OR NOT REGEXP_LIKE(',
'        l_sql,',
'        ''^\s*SELECT\s'',',
'        ''i''',
'    ) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Only SELECT statements are allowed.''',
'        );',
'    END IF;',
'',
'    -- Open cursor',
'    l_cursor := DBMS_SQL.OPEN_CURSOR;',
'',
'    DBMS_SQL.PARSE(',
'        l_cursor,',
'        l_sql,',
'        DBMS_SQL.NATIVE',
'    );',
'',
'    -- Get column metadata',
'    DBMS_SQL.DESCRIBE_COLUMNS2(',
'        l_cursor,',
'        l_column_count,',
'        l_columns',
'    );',
'',
'    -- Define dynamic columns',
'    FOR i IN 1 .. l_column_count LOOP',
'        DBMS_SQL.DEFINE_COLUMN(',
'            l_cursor,',
'            i,',
'            l_value,',
'            4000',
'        );',
'    END LOOP;',
'',
'    -- Execute query',
'    l_status := DBMS_SQL.EXECUTE(l_cursor);',
'',
'    -- Build JSON in memory',
'    APEX_JSON.INITIALIZE_CLOB_OUTPUT;',
'',
'    APEX_JSON.OPEN_OBJECT;',
'',
'    APEX_JSON.WRITE(''success'', TRUE);',
'',
'    -- Column metadata',
'    APEX_JSON.OPEN_ARRAY(''columns'');',
'',
'    FOR i IN 1 .. l_column_count LOOP',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(',
'            ''name'',',
'            l_columns(i).col_name',
'        );',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'',
'    -- Result rows',
'    APEX_JSON.OPEN_ARRAY(''rows'');',
'',
'    WHILE l_rows < 100',
'      AND DBMS_SQL.FETCH_ROWS(l_cursor) > 0',
'    LOOP',
'        APEX_JSON.OPEN_ARRAY;',
'',
'        FOR i IN 1 .. l_column_count LOOP',
'            DBMS_SQL.COLUMN_VALUE(',
'                l_cursor,',
'                i,',
'                l_value',
'            );',
'',
'            APEX_JSON.WRITE(l_value);',
'        END LOOP;',
'',
'        APEX_JSON.CLOSE_ARRAY;',
'',
'        l_rows := l_rows + 1;',
'    END LOOP;',
'',
'    APEX_JSON.CLOSE_ARRAY;',
'',
'    -- Close cursor',
'    DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'',
'    l_cursor := NULL;',
'',
'    -- Calculate execution time',
'    l_elapsed :=',
'        (DBMS_UTILITY.GET_TIME - l_start) / 100;',
'',
'    -- Mark query as successfully executed',
'    :P3_QUERY := l_sql;',
'    :P3_EXECUTED := ''Y'';',
'',
'    -- Execution information',
'    APEX_JSON.WRITE(''rowCount'', l_rows);',
'',
'    APEX_JSON.WRITE(',
'        ''executionTime'',',
'        l_elapsed',
'    );',
'',
'    APEX_JSON.WRITE(',
'        ''executed'',',
'        :P3_EXECUTED',
'    );',
'',
'    APEX_JSON.CLOSE_OBJECT;',
'',
'    -- Get complete JSON response',
'    l_json := APEX_JSON.GET_CLOB_OUTPUT;',
'',
'    APEX_JSON.FREE_OUTPUT;',
'',
'    -- Send JSON to browser',
'    SYS.HTP.PRN(l_json);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        l_error := SQLERRM;',
'',
'        -- Mark execution as failed',
'        :P3_EXECUTED := ''N'';',
'        :P3_QUERY := NULL;',
'',
'        -- Close cursor safely',
'        IF l_cursor IS NOT NULL THEN',
'            IF DBMS_SQL.IS_OPEN(l_cursor) THEN',
'                DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'            END IF;',
'        END IF;',
'',
'        -- Clean up any incomplete JSON',
'        BEGIN',
'            APEX_JSON.FREE_OUTPUT;',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'',
'        -- Return valid error JSON',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(''success'', FALSE);',
'',
'        APEX_JSON.WRITE(',
'            ''executed'',',
'            :P3_EXECUTED',
'        );',
'',
'        APEX_JSON.WRITE(',
'            ''error'',',
'            l_error',
'        );',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15672767851491119
,p_created_on=>wwv_flow_imp.dz('20261010133011Z')
,p_updated_on=>wwv_flow_imp.dz('20261010141403Z')
,p_created_by=>'DEMO'
,p_updated_by=>'DEMO'
);
wwv_flow_imp_page.create_page_process(
