wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15673939919491131)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Value'
,p_static_id=>'set-value'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sql          VARCHAR2(32767);',
'    l_cursor       INTEGER;',
'    l_column_count INTEGER;',
'    l_columns      DBMS_SQL.DESC_TAB2;',
'    l_column_name  VARCHAR2(32767);',
'    l_error        VARCHAR2(4000);',
'',
'    l_reserved     NUMBER;',
'',
'BEGIN',
'    -- Get SQL from Page 3',
'    l_sql := TRIM(:P3_SQL);',
'',
'    IF l_sql IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please execute a SELECT query before continuing.''',
'        );',
'    END IF;',
'',
'    -- Open cursor',
'    l_cursor := DBMS_SQL.OPEN_CURSOR;',
'',
'    DBMS_SQL.PARSE(',
'        l_cursor,',
'        l_sql,',
'        DBMS_SQL.NATIVE',
'    );',
'',
'    DBMS_SQL.DESCRIBE_COLUMNS2(',
'        l_cursor,',
'        l_column_count,',
'        l_columns',
'    );',
'',
'    -- Validate returned columns',
'    FOR i IN 1 .. l_column_count LOOP',
'',
'        l_column_name := UPPER(TRIM(l_columns(i).col_name));',
'',
'        -- Check invalid column names',
'        IF NOT REGEXP_LIKE(',
'            l_column_name,',
'            ''^[A-Z][A-Z0-9_$#]*$''',
'        ) THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20002,',
'                ''Column "'' || l_column_name ||',
'                ''" requires an alias. Example: AS COLUMN_NAME.''',
'            );',
'        END IF;',
'',
'        -- Check common expressions without aliases',
'        IF l_column_name IN (',
'            ''SYSDATE'',',
'            ''SYSTIMESTAMP'',',
'            ''CURRENT_DATE'',',
'            ''CURRENT_TIMESTAMP'',',
'            ''LOCALTIMESTAMP'',',
'            ''USER'',',
'            ''UID'',',
'            ''ROWNUM'',',
'            ''LEVEL''',
'        ) THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20003,',
'                ''Expression "'' || l_column_name ||',
'                ''" requires an alias. Example: '' ||',
'                l_column_name || '' AS COLUMN_NAME.''',
'            );',
'        END IF;',
'',
'    END LOOP;',
'',
'    DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'    l_cursor := NULL;',
'',
'    -- Transfer validated SQL',
'    :P4_SQL := l_sql;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        l_error := SQLERRM;',
'',
'        IF l_cursor IS NOT NULL THEN',
'            IF DBMS_SQL.IS_OPEN(l_cursor) THEN',
'                DBMS_SQL.CLOSE_CURSOR(l_cursor);',
'            END IF;',
'        END IF;',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20004,',
'            ''SQL validation failed: '' || l_error',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(15879878175870164)
,p_internal_uid=>15673939919491131
