wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15674412426491136)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CTAS'
,p_static_id=>'ctas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--DECLARE',
'--    l_table_name VARCHAR2(128);',
'--    l_sql        VARCHAR2(32767);',
'--    l_ctas       VARCHAR2(32767);',
'--    l_exists     NUMBER;',
'--',
'--BEGIN',
'--    -- Get dataset name',
'--    l_table_name := UPPER(TRIM(:P4_NOME_DATASET));',
'--',
'--    -- Get SELECT query',
'--    l_sql := TRIM(:P4_SQL);',
'--',
'--    -- Validate dataset name',
'--    IF NOT REGEXP_LIKE(',
'--        l_table_name,',
'--        ''^[A-Z][A-Z0-9]*(_[A-Z0-9]+)+$''',
'--    ) THEN',
'--        RAISE_APPLICATION_ERROR(',
'--            -20001,',
'--            ''Invalid dataset name. Example: SALES_DATASET''',
'--        );',
'--    END IF;',
'--',
'--    -- Validate SQL',
'--    IF l_sql IS NULL OR NOT REGEXP_LIKE(',
'--        l_sql,',
'--        ''^SELECT[[:space:]]'',',
'--        ''i''',
'--    ) THEN',
'--        RAISE_APPLICATION_ERROR(',
'--            -20002,',
'--            ''Only SELECT statements are allowed.''',
'--        );',
'--    END IF;',
'--',
'--    -- Validate table name',
'--    l_table_name := DBMS_ASSERT.SIMPLE_SQL_NAME(l_table_name);',
'--',
'--    -- Check if object already exists',
'--    SELECT COUNT(*)',
'--      INTO l_exists',
'--      FROM USER_OBJECTS',
'--     WHERE OBJECT_NAME = l_table_name;',
'--',
'--    IF l_exists > 0 THEN',
'--        RAISE_APPLICATION_ERROR(',
'--            -20004,',
'--            ''A database object with this name already exists.''',
'--        );',
'--    END IF;',
'--',
'--    -- Build CTAS preserving original column names',
'--    l_ctas :=',
'--        ''CREATE TABLE '' ||',
'--        l_table_name ||',
'--        '' PARALLEL 4 AS '' ||',
'--        l_sql;',
'--',
'--    -- Execute CTAS',
'--    EXECUTE IMMEDIATE l_ctas;',
'--',
'--    -- Register Dataset',
'--    INSERT INTO DATASETS (',
'--        DATASETS_NOME,',
'--        DESCRICAO,',
'--        DATASETS_SQL',
'--    )',
'--    VALUES (',
'--        l_table_name,',
'--        :P4_COMENTARIOS,',
'--        l_sql',
'--    );',
'--',
'--    -- Success message',
'--    APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'--        ''Dataset '' || l_table_name ||',
'--        '' created successfully!'';',
'--',
'--EXCEPTION',
'--    WHEN OTHERS THEN',
'--',
'--        IF SQLCODE = -998 THEN',
'--            APEX_ERROR.ADD_ERROR(',
'--                p_message =>',
'--                    ''Your SQL contains expressions without column aliases. '' ||',
'--                    ''Please add aliases using AS. '' ||',
'--                    ''Example: COUNT(*) AS TOTAL_EMPLOYEES.'',',
'--                p_display_location =>',
'--                    APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'--            );',
'--        ELSE',
'--            APEX_ERROR.ADD_ERROR(',
'--                p_message => SQLERRM,',
'--                p_display_location =>',
'--                    APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'--            );',
'--        END IF;',
'--',
'--END;',
'',
'',
'',
'',
'',
'DECLARE',
'    l_table_name    VARCHAR2(128);',
'    l_sql           VARCHAR2(32767);',
'    l_ctas          VARCHAR2(32767);',
'    l_exists        NUMBER;',
'',
'    l_original_service VARCHAR2(128);',
'    l_service_switched BOOLEAN := FALSE;',
'',
'    l_error_code    NUMBER;',
'    l_error_message VARCHAR2(4000);',
'',
'BEGIN',
'',
'    -- ==========================================',
'    -- 1. GET DATASET INFORMATION',
'    -- ==========================================',
'',
'    l_table_name := UPPER(TRIM(:P4_NOME_DATASET));',
'    l_sql        := TRIM(:P4_SQL);',
'',
'    -- ==========================================',
'    -- 2. VALIDATE DATASET NAME',
'    -- ==========================================',
'',
'    IF l_table_name IS NULL',
'       OR NOT REGEXP_LIKE(',
'           l_table_name,',
'           ''^[A-Z][A-Z0-9]*(_[A-Z0-9]+)+$''',
'       )',
'    THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Invalid dataset name. Example: SALES_DATASET''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 3. VALIDATE SQL',
'    -- ==========================================',
'',
'    IF l_sql IS NULL',
'       OR NOT REGEXP_LIKE(',
'           l_sql,',
'           ''^SELECT[[:space:]]'',',
'           ''i''',
'       )',
'    THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Only SELECT statements are allowed.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 4. VALIDATE TABLE NAME',
'    -- ==========================================',
'',
'    l_table_name :=',
'        DBMS_ASSERT.SIMPLE_SQL_NAME(l_table_name);',
'',
'    -- ==========================================',
'    -- 5. CHECK IF OBJECT EXISTS',
'    -- ==========================================',
'',
'    SELECT COUNT(*)',
'      INTO l_exists',
'      FROM USER_OBJECTS',
'     WHERE OBJECT_NAME = l_table_name;',
'',
'    IF l_exists > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20004,',
'            ''A database object with this name already exists.''',
'        );',
'    END IF;',
'',
'    -- ==========================================',
'    -- 6. BUILD PARALLEL CTAS',
'    -- ==========================================',
'',
'    l_ctas :=',
'        ''CREATE TABLE '' ||',
'        l_table_name ||',
'        '' PARALLEL 4 AS '' ||',
'        l_sql;',
'',
'    -- ==========================================',
'    -- 7. SAVE ORIGINAL SERVICE',
'    -- ==========================================',
'',
'    l_original_service :=',
'        SYS_CONTEXT(''USERENV'', ''SERVICE_NAME'');',
'',
'    APEX_DEBUG.MESSAGE(',
'        ''Original service: %s'',',
'        l_original_service',
'    );',
'',
'    -- ==========================================',
'    -- 8. SWITCH TO MEDIUM',
'    -- ==========================================',
'',
'    CS_SESSION.SWITCH_SERVICE(''MEDIUM'');',
'',
'    l_service_switched := TRUE;',
'',
'    APEX_DEBUG.MESSAGE(',
'        ''CTAS service: %s'',',
'        SYS_CONTEXT(''USERENV'', ''SERVICE_NAME'')',
'    );',
'',
'    -- ==========================================',
'    -- 9. ENABLE PARALLEL DDL',
'    -- ==========================================',
'',
'    EXECUTE IMMEDIATE',
'        ''ALTER SESSION ENABLE PARALLEL DDL'';',
'',
'    -- ==========================================',
'    -- 10. EXECUTE CTAS',
'    -- ==========================================',
'',
'    EXECUTE IMMEDIATE l_ctas;',
'',
'    -- ==========================================',
'    -- 11. DISABLE PARALLEL DDL',
'    -- ==========================================',
'',
'    EXECUTE IMMEDIATE',
'        ''ALTER SESSION DISABLE PARALLEL DDL'';',
'',
'    -- ==========================================',
'    -- 12. RESTORE ORIGINAL SERVICE',
'    -- ==========================================',
'',
'    CS_SESSION.SWITCH_SERVICE(''LOW'');',
'',
'    l_service_switched := FALSE;',
'',
'    -- ==========================================',
'    -- 13. REGISTER DATASET',
'    -- ==========================================',
'',
'    INSERT INTO DATASETS (',
'        DATASETS_NOME,',
'        DESCRICAO,',
'        DATASETS_SQL',
'    )',
'    VALUES (',
'        l_table_name,',
'        :P4_COMENTARIOS,',
'        l_sql',
'    );',
'',
'    -- ==========================================',
'    -- 14. SUCCESS MESSAGE',
'    -- ==========================================',
'',
'    APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'        ''Dataset '' || l_table_name ||',
'        '' created successfully using MEDIUM service (PARALLEL 4)!'';',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        l_error_code    := SQLCODE;',
'        l_error_message := SQLERRM;',
'',
'        -- ======================================',
'        -- RESTORE SESSION SETTINGS',
'        -- ======================================',
'',
'        BEGIN',
'            EXECUTE IMMEDIATE',
'                ''ALTER SESSION DISABLE PARALLEL DDL'';',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                APEX_DEBUG.ERROR(',
'                    ''Unable to disable Parallel DDL: %s'',',
'                    SQLERRM',
'                );',
'        END;',
'',
'        IF l_service_switched THEN',
'',
'            BEGIN',
'                CS_SESSION.SWITCH_SERVICE(''LOW'');',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    APEX_DEBUG.ERROR(',
'                        ''Unable to restore LOW service: %s'',',
'                        SQLERRM',
'                    );',
'            END;',
'',
'        END IF;',
'',
'        -- ======================================',
'        -- DISPLAY ERROR',
'        -- ======================================',
'',
'        IF l_error_code = -998 THEN',
'',
'            APEX_ERROR.ADD_ERROR(',
'                p_message =>',
'                    ''Your SQL contains expressions without column aliases. '' ||',
'                    ''Please add aliases using AS. '' ||',
'                    ''Example: COUNT(*) AS TOTAL_EMPLOYEES.'',',
'                p_display_location =>',
'                    APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'            );',
'',
'        ELSE',
'',
'            APEX_ERROR.ADD_ERROR(',
