,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sql CLOB;',
'BEGIN',
'',
'    SELECT',
'        descricao,',
'        datasets_usuario,',
'        TO_CHAR(',
'            datasets_data_criacao,',
'            ''DD/MM/YYYY HH24:MI:SS''',
'        ),',
'        datasets_sql',
'    INTO',
'        :P5_DESCRICAO,',
'        :P5_USUARIO,',
'        :P5_DATA_CRIACAO,',
'        l_sql',
'    FROM datasets',
'    WHERE datasets_nome = :P5_TABELA;',
'',
'    APEX_UTIL.SET_SESSION_STATE(',
'        p_name  => ''P5_SQL'',',
'        p_value => l_sql',
'    );',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Dataset not found.''',
'        );',
'',
'    WHEN TOO_MANY_ROWS THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Multiple datasets found for this ID.''',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15674553829491137
,p_created_on=>wwv_flow_imp.dz('20261010152740Z')
,p_updated_on=>wwv_flow_imp.dz('20261010153043Z')
